def check_graph(num_vertices, edges):
    degrees = [0] * num_vertices
    for u, v in edges:
        if not (0 <= u < num_vertices and 0 <= v < num_vertices):
            return False, "Vertex out of range"
        if u == v:
            return False, "Self-loop"
        degrees[u] += 1
        degrees[v] += 1

    for i, d in enumerate(degrees):
        if not (1 <= d <= 3):
            return False, f"Vertex {i} has degree {d}"
    return True, "Valid"

edges = [(2, 9), (2, 11), (2, 10), (0, 1), (3, 4), (5, 6), (7, 8)]
print(check_graph(12, edges))
